// C implementation of vstodo cmdBlame header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_blame.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_blame.go.\n\n#ifndef VSTODO_C_CMD_BLAME_H\n#define VSTODO_C_CMD_BLAME_H\n\n// Show who last modified each line of a file.\n// Equivalent to Go cmdBlame function.\n// app — vstodo application context pointer\n// args — file paths to blame\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_blame(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_BLAME_H